sources=json.loads('[{"name": "hnswlib_hnswalg.h", "url": "https://raw.githubusercontent.com/nmslib/hnswlib/v0.8.0/hnswlib/hnswalg.h", "sha256": "0fb2c1b1d3aae1ea959b536f96844f3f3ae6a2f32ce063f2c31f93d84a7e5c32"}, {"name": "Faiss_HNSW.cpp", "url": "https://raw.githubusercontent.com/facebookresearch/faiss/v1.15.1/faiss/impl/HNSW.cpp", "sha256": "80384738c1d5f25a3073fe13019816ed5eb5382d771071876b3d017438a61a69"}]')
for directory in ['data','results','sources','data/indices']:
    (root/directory).mkdir(parents=True,exist_ok=True)
for name,value in protocols.items():
    target=root/'results'/name
    if target.exists():
        if json.loads(target.read_text())!=value: raise RuntimeError('Existing protocol differs: '+name)
    else: target.write_text(json.dumps(value,indent=2))
if not a.config_only:
    for item in sources:
        target=root/'sources'/item['name']
        if not target.exists():
            response=requests.get(item['url'],timeout=60)
            response.raise_for_status()
            target.write_bytes(response.content)
        if hashlib.sha256(target.read_bytes()).hexdigest()!=item['sha256']: raise RuntimeError('Source hash mismatch: '+item['name'])
print('Native protocols and pinned sources ready')
